package agent

import (
	"context"
	"errors"
	"os/exec"
	"runtime"
	"strings"
	"testing"
	"time"
)

const windowsOS = "windows"

func TestRunIsolatedTextGeneratorCLIRaw_Success(t *testing.T) {
	t.Parallel()
	res, err := RunIsolatedTextGeneratorCLIRaw(context.Background(), nil, "echo", []string{"hello"}, "")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !strings.Contains(string(res.Stdout), "hello") {
		t.Errorf("Stdout = %q; want to contain 'hello'", res.Stdout)
	}
	if res.ExitCode != 0 {
		t.Errorf("ExitCode = %d; want 0", res.ExitCode)
	}
}

func TestRunIsolatedTextGeneratorCLIRaw_NonZeroExitReturnsBothResultAndError(t *testing.T) {
	t.Parallel()
	if runtime.GOOS == windowsOS {
		t.Skip("POSIX shell")
	}
	runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		return exec.CommandContext(ctx, "sh", "-c", "printf 'stdout data'; printf 'stderr data' 1>&2; exit 7")
	}
	res, err := RunIsolatedTextGeneratorCLIRaw(context.Background(), runner, "sh", nil, "")
	if err == nil {
		t.Fatal("want non-nil err on non-zero exit")
	}
	if string(res.Stdout) != "stdout data" {
		t.Errorf("Stdout = %q; want 'stdout data' even on failure", res.Stdout)
	}
	if string(res.Stderr) != "stderr data" {
		t.Errorf("Stderr = %q; want 'stderr data'", res.Stderr)
	}
	if res.ExitCode != 7 {
		t.Errorf("ExitCode = %d; want 7", res.ExitCode)
	}
}

func TestRunIsolatedTextGeneratorCLIRaw_BinaryNotFoundReturnsExecError(t *testing.T) {
	t.Parallel()
	_, err := RunIsolatedTextGeneratorCLIRaw(context.Background(), nil, "definitely-not-installed-binary-xyz", nil, "")
	if err == nil {
		t.Fatal("want error for missing binary")
	}
	// Downstream Classifier will use isExecNotFoundErr on this; the helper
	// should NOT pre-format it, just return the raw error.
	var execErr *exec.Error
	if !errors.As(err, &execErr) {
		t.Errorf("want wrappable *exec.Error; got %T: %v", err, err)
	}
}

func TestRunIsolatedTextGeneratorCLIRaw_StdinDelivered(t *testing.T) {
	t.Parallel()
	if runtime.GOOS == windowsOS {
		t.Skip("POSIX shell")
	}
	runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		return exec.CommandContext(ctx, "cat")
	}
	res, err := RunIsolatedTextGeneratorCLIRaw(context.Background(), runner, "cat", nil, "hello via stdin")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if string(res.Stdout) != "hello via stdin" {
		t.Errorf("Stdout = %q; want stdin echoed back", res.Stdout)
	}
}

func TestRunIsolatedTextGeneratorCLIRaw_CanceledContextPreservesSentinel(t *testing.T) {
	t.Parallel()
	if runtime.GOOS == windowsOS {
		t.Skip("POSIX shell")
	}
	runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		return exec.CommandContext(ctx, "sh", "-c", "sleep 10")
	}
	ctx, cancel := context.WithCancel(context.Background())
	go func() { time.Sleep(10 * time.Millisecond); cancel() }()
	_, err := RunIsolatedTextGeneratorCLIRaw(ctx, runner, "sh", nil, "")
	if err == nil {
		t.Fatal("want cancellation error")
	}
	// The caller's Classifier passes ctx errors through; the helper must not
	// wrap them in a way that defeats errors.Is.
	if !errors.Is(err, context.Canceled) && !errors.Is(ctx.Err(), context.Canceled) {
		t.Fatalf("want context.Canceled in chain; got %v", err)
	}
}

func TestStripGitEnv(t *testing.T) {
	t.Parallel()

	env := []string{
		"HOME=/home/user",
		"GIT_DIR=/some/dir",
		"PATH=/usr/bin",
		"GIT_WORK_TREE=/some/tree",
		"EDITOR=vim",
	}
	filtered := StripGitEnv(env)

	for _, e := range filtered {
		if strings.HasPrefix(e, "GIT_") {
			t.Fatalf("GIT_ variable not stripped: %s", e)
		}
	}
	if len(filtered) != 3 {
		t.Fatalf("expected 3 entries, got %d: %v", len(filtered), filtered)
	}
}

package cli

import (
	"context"
	"fmt"
	"os/exec"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/codex"
	"github.com/entireio/cli/cmd/entire/cli/agent/copilotcli"
	"github.com/entireio/cli/cmd/entire/cli/agent/cursor"
	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
)

// TestVerifyUserFacingErrors exercises the full chain for every (agent × scenario)
// combination and prints the user-facing message that renderTextGenError
// produces. Run with `go test -v -run TestVerifyUserFacingErrors`. This test
// is scaffolding for manual verification and is deleted after the audit.
func TestVerifyUserFacingErrors(t *testing.T) {
	t.Parallel()

	// fakeCmd returns a CommandRunner that ignores the provided binary path
	// and instead runs `sh -c <script>`. This simulates whatever stderr/
	// exit-code combination a real failing CLI would produce.
	fakeCmd := func(script string) agent.TextCommandRunner {
		return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
			return exec.CommandContext(ctx, "sh", "-c", script)
		}
	}
	missingCmd := func() agent.TextCommandRunner {
		return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
			return exec.CommandContext(ctx, "/nonexistent/binary/for/verification")
		}
	}

	type scenario struct {
		name   string
		runner agent.TextCommandRunner
	}

	scenarios := []scenario{
		{"CLIMissing", missingCmd()},
		{"Auth (401 passthrough)", fakeCmd(`printf 'ERROR: upstream request failed: 401 Unauthorized' 1>&2; exit 1`)},
		{"RateLimit (429 passthrough)", fakeCmd(`printf 'ERROR: rate limited, status 429 Too Many Requests' 1>&2; exit 1`)},
		{"Config (400 passthrough)", fakeCmd(`printf 'ERROR: bad request 400 invalid model' 1>&2; exit 1`)},
		{"Generic unknown failure", fakeCmd(`printf 'fatal: something nobody anticipated' 1>&2; exit 1`)},
		{"Empty stdout (exit 0 no output)", fakeCmd(`true`)},
		{"Success", fakeCmd(`printf 'generated summary content\n'`)},
	}

	type agentUnderTest struct {
		name     string
		callable func(agent.TextCommandRunner) (string, error)
	}

	agents := []agentUnderTest{
		{"claude-code", func(r agent.TextCommandRunner) (string, error) {
			return (&claudecode.ClaudeCodeAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"codex", func(r agent.TextCommandRunner) (string, error) {
			return (&codex.CodexAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"gemini", func(r agent.TextCommandRunner) (string, error) {
			return (&geminicli.GeminiCLIAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"cursor", func(r agent.TextCommandRunner) (string, error) {
			return (&cursor.CursorAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"copilot-cli", func(r agent.TextCommandRunner) (string, error) {
			return (&copilotcli.CopilotCLIAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
	}

	for _, ag := range agents {
		t.Run(ag.name, func(t *testing.T) {
			t.Parallel()
			for _, sc := range scenarios {
				out, err := ag.callable(sc.runner)
				rendered := renderForScenario(out, err)
				t.Logf("\n  [%-34s] %s", sc.name, rendered)
			}
		})
	}
}

// renderForScenario mimics what the user sees at the `entire explain` layer:
// either the generated summary text on success, or the output of
// renderTextGenError on a *agent.TextGenError. Context sentinels and other
// stray errors are printed raw so we notice them.
func renderForScenario(out string, err error) string {
	if err == nil {
		if out == "" {
			return "<success, empty output>"
		}
		return fmt.Sprintf("<success> %q", out)
	}
	var tge *agent.TextGenError
	if ok := errorsAs(err, &tge); ok {
		return renderTextGenError(tge).Error()
	}
	return fmt.Sprintf("<non-TextGenError> %T: %v", err, err)
}

// errorsAs is a thin wrapper so the test file doesn't need its own errors
// import separate from the helpers above.
func errorsAs(err error, target **agent.TextGenError) bool {
	for err != nil {
		if tge, ok := err.(*agent.TextGenError); ok {
			*target = tge
			return true
		}
		type unwrapper interface{ Unwrap() error }
		u, ok := err.(unwrapper)
		if !ok {
			return false
		}
		err = u.Unwrap()
	}
	return false
}

