package agent

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// TextGenErrorKind classifies a typed text-generation CLI error so callers can
// produce actionable user-facing messages without parsing strings.
type TextGenErrorKind string

const (
	// TextGenErrorAuth indicates an authentication or authorization failure
	// (HTTP 401/403, or provider-specific stderr phrase).
	TextGenErrorAuth TextGenErrorKind = "auth"
	// TextGenErrorRateLimit indicates the request was rejected for rate-limit
	// or quota reasons (HTTP 429).
	TextGenErrorRateLimit TextGenErrorKind = "rate_limit"
	// TextGenErrorConfig indicates a client-side request error other than
	// auth or rate-limit (e.g., HTTP 4xx for invalid model or malformed args).
	TextGenErrorConfig TextGenErrorKind = "config"
	// TextGenErrorCLIMissing indicates the provider's binary was not found on PATH.
	TextGenErrorCLIMissing TextGenErrorKind = "cli_missing"
	// TextGenErrorUnknown is the catch-all for failures we cannot classify.
	TextGenErrorUnknown TextGenErrorKind = "unknown"
)

// TextGenError is the shared typed error every summary provider's GenerateText
// returns on failure. APIStatus and ExitCode use 0 for "not applicable".
type TextGenError struct {
	Kind      TextGenErrorKind
	Provider  types.AgentName
	Message   string
	APIStatus int
	ExitCode  int
	Cause     error
}

func (e *TextGenError) Error() string {
	if e.Message == "" {
		if e.ExitCode != 0 {
			return fmt.Sprintf("%s CLI error (kind=%s, exit=%d)", e.Provider, e.Kind, e.ExitCode)
		}
		return fmt.Sprintf("%s CLI error (kind=%s)", e.Provider, e.Kind)
	}
	return fmt.Sprintf("%s CLI error (kind=%s): %s", e.Provider, e.Kind, e.Message)
}

func (e *TextGenError) Unwrap() error { return e.Cause }

// ExecResult is what RunIsolatedTextGeneratorCLIRaw returns: the raw pieces
// a caller needs to classify a subprocess outcome.
type ExecResult struct {
	Stdout   []byte
	Stderr   []byte
	ExitCode int
}

// stderrMessageMaxLen caps the Message field size when derived from stderr.
const stderrMessageMaxLen = 500

// TruncateStderr trims whitespace and caps stderr for use as a TextGenError
// Message. Shared across providers so the user-facing Message is predictable.
func TruncateStderr(s string) string {
	s = strings.TrimSpace(s)
	if len(s) > stderrMessageMaxLen {
		s = s[:stderrMessageMaxLen]
	}
	return s
}

// IsExecNotFoundErr reports whether err indicates the CLI binary was not found
// on PATH. Intentionally excludes other *exec.Error causes (permission denied,
// invalid executable format), which should surface as a generic failure so
// operators aren't misdirected to a reinstall when the real problem is a
// broken/inaccessible binary.
func IsExecNotFoundErr(err error) bool {
	if err == nil {
		return false
	}
	var execErr *exec.Error
	if errors.As(err, &execErr) && errors.Is(execErr.Err, exec.ErrNotFound) {
		return true
	}
	return errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist)
}

// ClassifyStderrHTTPStatus scans stderr for an HTTP status code and returns
// the matching error Kind. Most CLIs pass through their upstream API's HTTP
// status on failure, so this is the load-bearing classification signal.
// Returns TextGenErrorUnknown when no recognized status is present.
func ClassifyStderrHTTPStatus(stderr string) TextGenErrorKind {
	switch {
	case strings.Contains(stderr, "401"), strings.Contains(stderr, "403"):
		return TextGenErrorAuth
	case strings.Contains(stderr, "429"):
		return TextGenErrorRateLimit
	case strings.Contains(stderr, "400"), strings.Contains(stderr, "404"):
		return TextGenErrorConfig
	}
	return TextGenErrorUnknown
}

package agent

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"testing"
)

func TestTextGenError_ErrorIncludesKindAndMessage(t *testing.T) {
	t.Parallel()
	e := &TextGenError{Kind: TextGenErrorAuth, Provider: AgentNameClaudeCode, Message: "Invalid API key"}
	s := e.Error()
	if !strings.Contains(s, "auth") {
		t.Errorf("Error() = %q; want to contain kind 'auth'", s)
	}
	if !strings.Contains(s, "Invalid API key") {
		t.Errorf("Error() = %q; want to contain message", s)
	}
}

func TestTextGenError_UnwrapReturnsCause(t *testing.T) {
	t.Parallel()
	cause := errors.New("underlying")
	e := &TextGenError{Kind: TextGenErrorUnknown, Cause: cause}
	if got := errors.Unwrap(e); !errors.Is(got, cause) {
		t.Errorf("Unwrap() = %v; want %v", got, cause)
	}
}

func TestTextGenError_ErrorEmptyMessageIncludesExitCode(t *testing.T) {
	t.Parallel()
	e := &TextGenError{Kind: TextGenErrorUnknown, Provider: AgentNameClaudeCode, ExitCode: 137}
	want := "claude-code CLI error (kind=unknown, exit=137)"
	if got := e.Error(); got != want {
		t.Errorf("Error() = %q; want %q", got, want)
	}
}

func TestTextGenError_ErrorsAsIntegration(t *testing.T) {
	t.Parallel()
	cause := errors.New("timeout")
	wrapped := fmt.Errorf("operation failed: %w", &TextGenError{
		Kind:     TextGenErrorCLIMissing,
		Provider: AgentNameCodex,
		Message:  "codex not found",
		Cause:    cause,
	})

	var tge *TextGenError
	if !errors.As(wrapped, &tge) {
		t.Fatal("errors.As did not find *TextGenError in wrapped chain")
	}
	if tge.Kind != TextGenErrorCLIMissing {
		t.Errorf("Kind = %q; want %q", tge.Kind, TextGenErrorCLIMissing)
	}
	if !errors.Is(tge, cause) {
		t.Error("errors.Is did not find cause through TextGenError.Unwrap()")
	}
}

func TestClassifyStderrHTTPStatus(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name   string
		stderr string
		want   TextGenErrorKind
	}{
		{"401 maps to auth", "ERROR: 401 Unauthorized", TextGenErrorAuth},
		{"403 maps to auth", "ERROR: 403 Forbidden", TextGenErrorAuth},
		{"429 maps to rate_limit", "ERROR: 429 Too Many Requests", TextGenErrorRateLimit},
		{"400 maps to config", "ERROR: 400 Bad Request", TextGenErrorConfig},
		{"404 maps to config", "ERROR: 404 Not Found", TextGenErrorConfig},
		{"no status maps to unknown", "something weird and unclassifiable", TextGenErrorUnknown},
		{"empty maps to unknown", "", TextGenErrorUnknown},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := ClassifyStderrHTTPStatus(tc.stderr); got != tc.want {
				t.Errorf("ClassifyStderrHTTPStatus(%q) = %q; want %q", tc.stderr, got, tc.want)
			}
		})
	}
}

func TestTruncateStderr(t *testing.T) {
	t.Parallel()
	long := strings.Repeat("x", 800)
	got := TruncateStderr(long)
	if len(got) > stderrMessageMaxLen {
		t.Errorf("len = %d; want <= %d", len(got), stderrMessageMaxLen)
	}
	if got := TruncateStderr("  hello  "); got != "hello" {
		t.Errorf("TruncateStderr trims whitespace = %q; want 'hello'", got)
	}
}

func TestIsExecNotFoundErr(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		err  error
		want bool
	}{
		{"exec.Error wrapping ErrNotFound", &exec.Error{Name: "codex", Err: exec.ErrNotFound}, true},
		{"top-level exec.ErrNotFound", exec.ErrNotFound, true},
		{"os.ErrNotExist", os.ErrNotExist, true},
		{"wrapped exec.ErrNotFound via fmt.Errorf", fmt.Errorf("spawn failed: %w", exec.ErrNotFound), true},
		{"permission denied is NOT CLI-missing", &exec.Error{Name: "x", Err: os.ErrPermission}, false},
		{"nil is NOT CLI-missing", nil, false},
		{"arbitrary error is NOT CLI-missing", errors.New("some other failure"), false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := IsExecNotFoundErr(tc.err); got != tc.want {
				t.Errorf("IsExecNotFoundErr(%v) = %v; want %v", tc.err, got, tc.want)
			}
		})
	}
}

package claudecode

import (
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// classifyClaudeEnvelope inspects Claude CLI stdout for the structured JSON
// envelope and returns a typed *TextGenError when the envelope represents a
// failure, nil otherwise.
//
// Return contract:
//   - nil: no envelope to classify. Reached when stdout is empty (subprocess
//     produced no output — e.g. CLIMissing or SIGKILL before any writes) OR
//     when the envelope parsed cleanly with is_error:false (success path).
//   - non-nil: structured failure — either an is_error:true envelope
//     classified by api_error_status / auth-phrase heuristic, or a malformed-
//     JSON case (stdout non-empty but unparseable).
//
// The empty-stdout carveout preserves 963's fallthrough semantics: when the
// subprocess died before emitting anything, the envelope path must not
// preempt CLIMissing / stderr / ctx-sentinel classification done by the
// caller.
func classifyClaudeEnvelope(stdout []byte) *agent.TextGenError {
	if len(stdout) == 0 {
		return nil
	}
	result, envelope, parseErr := parseGenerateTextResponse(stdout)
	if parseErr != nil {
		return &agent.TextGenError{
			Kind:     agent.TextGenErrorUnknown,
			Provider: agent.AgentNameClaudeCode,
			Message:  fmt.Sprintf("failed to parse claude CLI response: %v", parseErr),
		}
	}
	if envelope == nil || !envelope.IsError {
		return nil
	}
	apiStatus := 0
	if envelope.APIErrorStatus != nil {
		apiStatus = *envelope.APIErrorStatus
	}
	e := &agent.TextGenError{
		Provider:  agent.AgentNameClaudeCode,
		Message:   result,
		APIStatus: apiStatus,
	}
	switch {
	case apiStatus == 401, apiStatus == 403:
		e.Kind = agent.TextGenErrorAuth
	case apiStatus == 429:
		e.Kind = agent.TextGenErrorRateLimit
	case apiStatus >= 400 && apiStatus < 500:
		e.Kind = agent.TextGenErrorConfig
	case apiStatus == 0 && containsAuthPhrase(result):
		// Last-resort heuristic for envelopes that carry is_error:true
		// without a structured api_error_status. Small, evidence-based list
		// from 963.
		e.Kind = agent.TextGenErrorAuth
	default:
		e.Kind = agent.TextGenErrorUnknown
	}
	return e
}

var envelopeAuthPhrases = []string{"invalid api key", "not logged in"}

func containsAuthPhrase(s string) bool {
	lower := strings.ToLower(s)
	for _, p := range envelopeAuthPhrases {
		if strings.Contains(lower, p) {
			return true
		}
	}
	return false
}

package claudecode

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText sends a prompt to the Claude CLI and returns the raw text response.
// Implements the agent.TextGenerator interface.
//
// Model defaults to "haiku" for fast, cheap generation (the summarize package
// overrides to "sonnet" via ResolveModel for quality).
//
// Classification order:
//  1. Envelope on stdout — checked first because Claude's primary failure mode
//     is exit 0 with is_error:true; the structured envelope wins over stderr
//     and ctx sentinels.
//  2. Context sentinels (ctx canceled/deadline) — passthrough, not typed.
//  3. CLIMissing — typed error for "install the binary" remediation.
//  4. Any other run error — stderr classified by HTTP status.
//  5. Empty stdout on exit 0 — typed Unknown with "empty output" message.
func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
	if model == "" {
		model = "haiku"
	}
	args := []string{
		"--print", "--output-format", "json",
		"--model", model, "--setting-sources", "",
	}
	res, runErr := agent.RunIsolatedTextGeneratorCLIRaw(ctx, c.CommandRunner, "claude", args, prompt)

	if env := classifyClaudeEnvelope(res.Stdout); env != nil {
		env.ExitCode = res.ExitCode
		env.Cause = runErr
		return "", env
	}

	if runErr != nil {
		if errors.Is(runErr, context.Canceled) {
			return "", context.Canceled
		}
		if errors.Is(runErr, context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if agent.IsExecNotFoundErr(runErr) {
			return "", &agent.TextGenError{
				Kind:     agent.TextGenErrorCLIMissing,
				Provider: agent.AgentNameClaudeCode,
				Cause:    runErr,
			}
		}
		stderr := agent.TruncateStderr(string(res.Stderr))
		return "", &agent.TextGenError{
			Kind:     agent.ClassifyStderrHTTPStatus(stderr),
			Provider: agent.AgentNameClaudeCode,
			Message:  stderr,
			ExitCode: res.ExitCode,
			Cause:    runErr,
		}
	}

	// Success path. Envelope was nil (stdout empty) or envelope.IsError was false.
	if len(res.Stdout) == 0 {
		return "", &agent.TextGenError{
			Kind:     agent.TextGenErrorUnknown,
			Provider: agent.AgentNameClaudeCode,
			Message:  "claude CLI returned empty output",
		}
	}
	result, _, parseErr := parseGenerateTextResponse(res.Stdout)
	if parseErr != nil {
		return "", &agent.TextGenError{
			Kind:     agent.TextGenErrorUnknown,
			Provider: agent.AgentNameClaudeCode,
			Message:  fmt.Sprintf("unexpected parse failure on success path: %v", parseErr),
			Cause:    parseErr,
		}
	}
	return result, nil
}

