func TestVerifyUserFacingErrors(t *testing.T) {
	t.Parallel()

	fakeCmd := func(script string) agent.TextCommandRunner {
		return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
			return exec.CommandContext(ctx, "sh", "-c", script)
		}
	}
	missingCmd := func() agent.TextCommandRunner {
		return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
			return exec.CommandContext(ctx, "/nonexistent/binary/for/verification")
		}
	}

	type scenario struct {
		name   string
		runner agent.TextCommandRunner
	}
	scenarios := []scenario{
		{"CLIMissing", missingCmd()},
		{"Auth (401 passthrough)", fakeCmd(`printf 'ERROR: upstream request failed: 401 Unauthorized' 1>&2; exit 1`)},
		{"RateLimit (429 passthrough)", fakeCmd(`printf 'ERROR: rate limited, status 429 Too Many Requests' 1>&2; exit 1`)},
		{"Config (400 passthrough)", fakeCmd(`printf 'ERROR: bad request 400 invalid model' 1>&2; exit 1`)},
		{"Generic unknown failure", fakeCmd(`printf 'fatal: something nobody anticipated' 1>&2; exit 1`)},
		{"Empty stdout (exit 0 no output)", fakeCmd(`true`)},
		{"Success", fakeCmd(`printf 'generated summary content\n'`)},
	}

	type agentUnderTest struct {
		name     string
		callable func(agent.TextCommandRunner) (string, error)
	}
	agents := []agentUnderTest{
		{"claude-code", func(r agent.TextCommandRunner) (string, error) {
			return (&claudecode.ClaudeCodeAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"codex", func(r agent.TextCommandRunner) (string, error) {
			return (&codex.CodexAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"gemini", func(r agent.TextCommandRunner) (string, error) {
			return (&geminicli.GeminiCLIAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"cursor", func(r agent.TextCommandRunner) (string, error) {
			return (&cursor.CursorAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
		{"copilot-cli", func(r agent.TextCommandRunner) (string, error) {
			return (&copilotcli.CopilotCLIAgent{CommandRunner: r}).GenerateText(context.Background(), "prompt", "")
		}},
	}

	for _, ag := range agents {
		t.Run(ag.name, func(t *testing.T) {
			t.Parallel()
			for _, sc := range scenarios {
				out, err := ag.callable(sc.runner)
				rendered := renderForScenario(out, err)
				t.Logf("\n  [%-34s] %s", sc.name, rendered)
			}
		})
	}
}

func renderForScenario(out string, err error) string {
	if err == nil {
		if out == "" {
			return "<success, empty output>"
		}
		return fmt.Sprintf("<success> %q", out)
	}
	var tge *agent.TextGenError
	if ok := errorsAs(err, &tge); ok {
		return renderTextGenError(tge).Error()
	}
	return fmt.Sprintf("<non-TextGenError> %T: %v", err, err)
}

func errorsAs(err error, target **agent.TextGenError) bool {
	for err != nil {
		if tge, ok := err.(*agent.TextGenError); ok {
			*target = tge
			return true
		}
		type unwrapper interface{ Unwrap() error }
		u, ok := err.(unwrapper)
		if !ok {
			return false
		}
		err = u.Unwrap()
	}
	return false
}

